CREATE TABLE "dim_location" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL
);

CREATE TABLE "dim_charger" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "location_id" bigint NOT NULL,
  "type" text NOT NULL
);

CREATE TABLE "dim_user" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "car_model" text NOT NULL,
  "membership_type" text NOT NULL
);

CREATE TABLE "dim_date" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "iso" varchar NOT NULL,
  "day" integer NOT NULL,
  "month" integer NOT NULL,
  "year" integer NOT NULL,
  "day_of_week" "enum(Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday)" NOT NULL,
  "week" integer NOT NULL
);

CREATE TABLE "dim_time" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "date_id" bigint NOT NULL,
  "time_of_day" "enum(Morning,Afternoon,Evening,Night)" NOT NULL,
  "hours" integer NOT NULL,
  "minutes" integer NOT NULL
);

CREATE TABLE "facts_charges" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "charger_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "start_time" bigint NOT NULL,
  "end_time" bigint NOT NULL,
  "duration_hours" float NOT NULL,
  "energy_consumed_kwh" float NOT NULL,
  "charging_rate_kwh" float NOT NULL,
  "charging_cost_kwh" float NOT NULL,
  "battery_percentage_start" float NOT NULL,
  "battery_percentage_end" float NOT NULL,
  "vehicle_age_years" float NOT NULL,
  "distance_since_last_charge_km" float NOT NULL,
  "ambient_temperature_celsius" float NOT NULL
);

ALTER TABLE "dim_charger" ADD FOREIGN KEY ("location_id") REFERENCES "dim_location" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "dim_time" ADD FOREIGN KEY ("date_id") REFERENCES "dim_date" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "facts_charges" ADD FOREIGN KEY ("charger_id") REFERENCES "dim_charger" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "facts_charges" ADD FOREIGN KEY ("user_id") REFERENCES "dim_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "facts_charges" ADD FOREIGN KEY ("start_time") REFERENCES "dim_time" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "facts_charges" ADD FOREIGN KEY ("end_time") REFERENCES "dim_time" ("id") DEFERRABLE INITIALLY IMMEDIATE;
